/** Pure conversion controls; mocking term IDs does not grant semantic graph or snapshot authority. */
class LmdbFrontierReadPopulationTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI P = VF.createIRI("urn:population:p");
	private static final IRI O = VF.createIRI("urn:population:o");
	private static final IRI G = VF.createIRI("urn:population:g");
	private static final IRI UNKNOWN = VF.createIRI("urn:population:unknown");

	@Test
	void onlyUnspecifiedDatasetSelectionUsesStoreDefaults() {
		assertEquals(LmdbFrontierReadPopulation.STORE_DEFAULTS, LmdbFrontierReadPopulation.forDataset(null));
		assertEquals(LmdbFrontierReadPopulation.STORE_DEFAULTS,
				LmdbFrontierReadPopulation.forDataset(new SimpleDataset()));
		SimpleDataset explicit = new SimpleDataset();
		explicit.setExplicitReadDataset(true);
		assertEquals(LmdbFrontierReadPopulation.UNSUPPORTED, LmdbFrontierReadPopulation.forDataset(explicit));
		SimpleDataset selectedDefault = new SimpleDataset();
		selectedDefault.addDefaultGraph(G);
		assertEquals(LmdbFrontierReadPopulation.UNSUPPORTED,
				LmdbFrontierReadPopulation.forDataset(selectedDefault));
		SimpleDataset selectedNamed = new SimpleDataset();
		selectedNamed.addNamedGraph(G);
		assertEquals(LmdbFrontierReadPopulation.UNSUPPORTED,
				LmdbFrontierReadPopulation.forDataset(selectedNamed));
		Dataset unknown = mock(Dataset.class);
		when(unknown.getDefaultGraphResources()).thenReturn(null);
		assertEquals(LmdbFrontierReadPopulation.UNSUPPORTED, LmdbFrontierReadPopulation.forDataset(unknown));
	}

	@Test
	void oldPhysicalFactoryAndOwnedStoreDefaultFactoryRemainSeparate() throws Exception {
		ValueStore values = values();
		StatementPattern pattern = pattern("s", "o");
		FrontierLeafProbe legacy = LmdbFrontierProbeFactory.probe(values, pattern, FrontierLeafProbe.EXPLICIT);
		FrontierLeafProbe owned = LmdbFrontierProbeFactory.probe(values, pattern, FrontierLeafProbe.EXPLICIT,
				LmdbFrontierReadPopulation.STORE_DEFAULTS);
		assertEquals(FrontierLeafProbe.PREDICATE | FrontierLeafProbe.CONTEXT, legacy.boundMask());
		assertEquals(0L, legacy.contextId());
		assertEquals(FrontierLeafProbe.PREDICATE, owned.boundMask());
		assertEquals(FrontierLeafProbe.EXPLICIT, owned.planeMask());
		assertFalse(owned.namedContextsOnly());
		FrontierLeafProbe raw = LmdbFrontierProbeFactory.probe(values, null, P, null, null,
				FrontierLeafProbe.INFERRED, 0);
		assertEquals(FrontierLeafProbe.PREDICATE, raw.boundMask());
		assertEquals(FrontierLeafProbe.INFERRED, raw.planeMask());
	}

	@Test
	void namedFixedUnknownAndDefaultAliasSelectorsRetainTheirOwnMeaning() throws Exception {
		ValueStore values = values();
		StatementPattern named = namedPattern(Var.of("g"));
		FrontierLeafProbe unbound = LmdbFrontierProbeFactory.probe(values, named, FrontierLeafProbe.BOTH_PLANES,
				LmdbFrontierReadPopulation.STORE_DEFAULTS);
		assertTrue(unbound.namedContextsOnly());
		assertEquals(FrontierLeafProbe.PREDICATE, unbound.boundMask());
		named = namedPattern(Var.of("g", G));
		FrontierLeafProbe fixed = LmdbFrontierProbeFactory.probe(values, named, FrontierLeafProbe.BOTH_PLANES,
				LmdbFrontierReadPopulation.STORE_DEFAULTS);
		assertEquals(FrontierLeafProbe.PREDICATE | FrontierLeafProbe.CONTEXT, fixed.boundMask());
		assertEquals(13L, fixed.contextId());
		named = namedPattern(Var.of("g", UNKNOWN));
		assertNull(LmdbFrontierProbeFactory.probe(values, named, FrontierLeafProbe.BOTH_PLANES,
				LmdbFrontierReadPopulation.STORE_DEFAULTS));
		for (IRI alias : List.of(RDF4J.NIL, SESAME.NIL)) {
			named = namedPattern(Var.of("g", alias));
			FrontierLeafProbe normalized = LmdbFrontierProbeFactory.probe(values, named,
					FrontierLeafProbe.BOTH_PLANES, LmdbFrontierReadPopulation.STORE_DEFAULTS);
			assertEquals(0L, normalized.contextId());
			assertEquals(FrontierLeafProbe.PREDICATE | FrontierLeafProbe.CONTEXT, normalized.boundMask());
		}
	}

	@Test
	void lineageAliasesBindingsAndJoinProgramsShareTheOwnedPopulation() throws Exception {
		ValueStore values = values();
		StatementPattern first = pattern("s", "o");
		Extension alias = new Extension(first, new ExtensionElem(Var.of("s"), "copy"));
		StatementPattern second = pattern("copy", "next");
		StatementPattern third = pattern("next", "end");
		FrontierLeafProbe bound = LmdbFrontierProbeFactory.probeForLineage(values, alias, Map.of("copy", O),
				FrontierLeafProbe.BOTH_PLANES, LmdbFrontierReadPopulation.STORE_DEFAULTS);
		assertEquals(FrontierLeafProbe.SUBJECT | FrontierLeafProbe.PREDICATE, bound.boundMask());
		assertEquals(11L, bound.subjectId());
		var pair = LmdbFrontierProbeFactory.joinProbeForLineage(values, alias, second,
				FrontierLeafProbe.BOTH_PLANES, LmdbFrontierReadPopulation.STORE_DEFAULTS);
		assertNotNull(pair);
		assertEquals(0, pair.left().boundMask() & FrontierLeafProbe.CONTEXT);
		assertEquals(0, pair.right().boundMask() & FrontierLeafProbe.CONTEXT);
		FrontierJoinProgram program = LmdbFrontierProbeFactory.joinProgramForLineage(values,
				List.of(new Join(alias, second), third), FrontierLeafProbe.BOTH_PLANES,
				LmdbFrontierReadPopulation.STORE_DEFAULTS);
		assertEquals(3, program.patternCount());
		for (int index = 0; index < program.patternCount(); index++) {
			assertEquals(0, program.pattern(index).boundMask() & FrontierLeafProbe.CONTEXT);
		}
		List<TupleExpr> factors = List.of(alias, second);
		assertNull(LmdbFrontierProbeFactory.probeForLineage(values, alias, FrontierLeafProbe.BOTH_PLANES,
				LmdbFrontierReadPopulation.UNSUPPORTED));
		assertNull(LmdbFrontierProbeFactory.joinProbeForLineage(values, factors, FrontierLeafProbe.BOTH_PLANES,
				LmdbFrontierReadPopulation.UNSUPPORTED));
		assertNull(LmdbFrontierProbeFactory.joinProgramForLineage(values, factors, FrontierLeafProbe.BOTH_PLANES,
				LmdbFrontierReadPopulation.UNSUPPORTED));
	}

	@Test
	void estimatorContextsAndSemanticCacheKeysKeepThePopulationCoordinate() {
		StatementPattern pattern = pattern("s", "o");
		EstimateContext physical = EstimateContext.root(pattern, new QuadSnapshotIdentity(1L, 2L, 3L), 4L);
		EstimateContext owned = physical.withReadPopulation(LmdbFrontierReadPopulation.STORE_DEFAULTS);
		assertNotEquals(SemanticEstimateCacheKey.of(pattern, physical, null),
				SemanticEstimateCacheKey.of(pattern, owned, null));
		assertEquals(LmdbFrontierReadPopulation.STORE_DEFAULTS,
				owned.withBoundNames(List.of("s")).withInvocationCount(2.0d).readPopulation());
		assertEquals(physical.nativeEvidenceAllowed(),
				owned.withReadPopulation(LmdbFrontierReadPopulation.UNSUPPORTED).nativeEvidenceAllowed(),
				"Frontier selection must not alter independent graph-evidence eligibility");
		EstimateContext explicit = owned.withReadPopulation(LmdbFrontierReadPopulation.STORE_DEFAULTS,
				FrontierLeafProbe.EXPLICIT);
		EstimateContext inferred = owned.withReadPopulation(LmdbFrontierReadPopulation.STORE_DEFAULTS,
				FrontierLeafProbe.INFERRED);
		assertNotEquals(SemanticEstimateCacheKey.of(pattern, explicit, null),
				SemanticEstimateCacheKey.of(pattern, inferred, null));
		assertEquals(FrontierLeafProbe.EXPLICIT,
				explicit.withBoundNames(List.of("s")).withInvocationCount(2.0d).frontierPlaneMask());
	}

	private static StatementPattern namedPattern(Var graph) {
		return new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("s"), Var.of("p", P), Var.of("o"),
				graph);
	}

	private static StatementPattern pattern(String subject, String object) {
		return new StatementPattern(Var.of(subject), Var.of("p", P), Var.of(object));
	}

	private static ValueStore values() throws Exception {
		ValueStore values = mock(ValueStore.class);
		when(values.getId(P)).thenReturn(7L);
		when(values.getId(O)).thenReturn(11L);
		when(values.getId(G)).thenReturn(13L);
		when(values.getId(UNKNOWN)).thenReturn(LmdbValue.UNKNOWN_ID);
		return values;
	}
}
